/**
 * MorphoNews Layout: キネティック・デプス・プリズム
 * Generated: 2026-02-27_0957
 * Generation: #91
 * Mood: Transformative
 * Evolution: Scroll-driven 3D Rotation + transform-origin staggering + dynamic backdrop-blur layering
 * Description: 第92世代の進化として、前回の「情報の論理的結合（Assembly）」から、空間的な「多次元的展開（Depth & Unfolding）」へとパラダイムを移行しました。垂直スクロールをトリガーとし、中央の仮想的な軸からニュースカードが3D空間上で本をめくるように展開される「プリズム・アンフォールディング」を採用。Scroll-driven Animationsを活用し、スクロール位置に応じて各カードのrotateYとtranslateZを動的に制御することで、平面的なグリッドを奥行きのある体験へと変換しています。また、カードの重なり部分に強力なbackdrop-filterを適用し、背後のコンテンツが屈折して見える視覚効果を付加しました。
 */
/**
 * MorphoNews Layout: Kinetic Depth Prism
 * Generation: #92
 * Mood: Transformative / 3D-Spatial
 */

:root {
    --layout-max-width: 1400px;
    --layout-news-columns: repeat(2, 1fr);
    --layout-card-gap: 4rem;
    --layout-card-direction: column;
    --layout-animation-style: prism-unfold;
    --perspective-value: 2500px;
}

#news-container {
    display: grid;
    grid-template-columns: var(--layout-news-columns);
    gap: var(--layout-card-gap);
    max-width: var(--layout-max-width);
    margin: 4rem auto;
    padding: 0 2rem;
    perspective: var(--perspective-value);
    perspective-origin: center top;
}

.news-card {
    position: relative;
    height: 500px;
    background: var(--morpho-bg-secondary);
    border: 1px solid rgba(255, 255, 255, 0.1);
    border-radius: 1px; /* Sharp edge for prism look */
    backdrop-filter: blur(12px) saturate(180%);
    overflow: hidden;

    /* Scroll-driven Animation Setup */
    view-timeline: --card-timeline block;
    animation: prism-unfold linear both;
    animation-timeline: --card-timeline;
    animation-range: entry 0% cover 50%;
}

/* 奇数番目：右から開く */
.news-card:nth-child(odd) {
    transform-origin: left center;
    margin-right: -1rem;
}

/* 偶数番目：左から開く */
.news-card:nth-child(even) {
    transform-origin: right center;
    margin-left: -1rem;
    margin-top: 5rem; /* Staggered vertical flow */
}

@keyframes prism-unfold {
    0% {
        opacity: 0;
        transform: 
            rotateY(var(--rotate-dir, 45deg)) 
            translateZ(-400px) 
            scale(0.8);
        filter: brightness(0.5) blur(4px);
    }
    100% {
        opacity: 1;
        transform: 
            rotateY(0deg) 
            translateZ(0) 
            scale(1);
        filter: brightness(1) blur(0);
    }
}

/* Set specific rotation for odd/even */
.news-card:nth-child(odd) { --rotate-dir: -45deg; }
.news-card:nth-child(even) { --rotate-dir: 45deg; }

.news-card::after {
    content: '';
    position: absolute;
    inset: 0;
    background: linear-gradient(
        135deg, 
        rgba(255,255,255,0.1) 0%, 
        transparent 50%, 
        rgba(0,0,0,0.2) 100%
    );
    pointer-events: none;
}

.news-card:hover {
    z-index: 100;
    border-color: var(--morpho-accent-primary);
    transition: border-color 0.4s ease, transform 0.4s cubic-bezier(0.175, 0.885, 0.32, 1.275);
    transform: scale(1.02) translateZ(50px) !important;
}

